* Power Supplies
VDD VDD 0 DC 1.8 AC 0
VSS GND 0 DC 0

* Instance 1: AC Open-Loop / CMRR / PSRR Characterization (Fig. 24.25 setup)
* Using large inductor and capacitor for DC feedback and AC open-loop
XDUT1 vin_ac vfb_ac vout_ac VDD GND OPAMP_DUT
Lfb1 vout_ac vfb_ac 1000MEG
Cfb1 vfb_ac 0 10u
Vac_diff vin_ac 0 DC 0.7 AC 1

* Instance 2: Large-Signal Transient Step Response (Fig. 24.14 / Fig. 24.23)
XDUT2 vin_step vout_step vout_step VDD GND OPAMP_DUT
Vin_pulse vin_step 0 PULSE(0.5 0.9 450n 1n 1n 250n 1u)

.control
save all

* 1. DC Operating Point & Power
op
let power = -i(VDD) * 1.8
print power

* 2. AC Open-Loop Frequency Response
ac dec 100 10 1G
let aol_db = vdb(vout_ac)
let aol_phase = 180 + (180/PI * cph(v(vout_ac)))

meas ac aol_dc find vdb(vout_ac) at=10
meas ac fun when aol_db=0 fall=1
meas ac phase_margin find aol_phase when aol_db=0 fall=1

* 3. Transient Step Response (500 mV to 900 mV)
tran 0.5n 1u 400n

* Measure Slew Rates
meas tran sr_pos trig v(vout_step) val=0.55 rise=1 targ v(vout_step) val=0.85 rise=1
let sr_pos_val = 0.3 / (sr_pos + 1e-15) * 1e-6
print sr_pos_val

meas tran sr_neg trig v(vout_step) val=0.85 fall=1 targ v(vout_step) val=0.55 fall=1
let sr_neg_val = 0.3 / (sr_neg + 1e-15) * 1e-6
print sr_neg_val

* Measure Settling Times
meas tran t_settle_rise trig v(vin_step) val=0.7 rise=1 targ v(vout_step) val=0.896 rise=1
meas tran t_settle_fall trig v(vin_step) val=0.7 fall=1 targ v(vout_step) val=0.504 fall=1

quit
.endc
.end

